{"path":"src/java_module.java","content":"// Метод ищет активного пользователя по логину.
// Возвращает Optional<User>, чтобы явно показать, что пользователь может отсутствовать,
// а не возвращать null (это защищает вызывающий код от NullPointerException).
public Optional<User> findActive(String login) {
    // Берём поток из коллекции всех пользователей.
    return users.stream()
        // Первый фильтр: совпадение логина без учёта регистра.
        // Используем equalsIgnoreCase, потому что пользователи могут вводить
        // логин в любом регистре, а хранить его мы хотим в едином формате.
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Второй фильтр: пользователь должен быть активным.
        // Активность определяется двумя условиями:
        //   1) пользователь не заблокирован (!u.isBlocked());
        //   2) срок действия учётной записи ещё не истёк
        //      (getExpiresAt() строго позже текущего момента времени).
        // Объединяем условия через && — оба должны выполняться одновременно.
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Берём только первый найденный подходящий элемент.
        // findFirst() эффективнее, чем собрать все совпадения в список,
        // так как останавливает обход при первом же совпадении.
        .findFirst();
}
"}

{"path":"src/csharp_module.cs","content":"// Метод повторяет выполнение асинхронного действия с экспоненциальной задержкой.
// Используется для устойчивости к временным сбоям сети (например, таймаутам).
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Перебираем попытки от 0 до attempts-1.
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Выполняем действие и сразу возвращаем результат при успехе.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        // Перехватываем только сетевые ошибки.
        // Условие "when" гарантирует, что на последней попытке
        // исключение пробрасывается наружу, а не глотается.
        {
            // Экспоненциальная задержка: 200мс * 2^i.
            // Даём серверу время восстановиться перед повтором.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Достигается только если все попытки исчерпаны без возврата.
    // На практике это недостижимо, т.к. либо вернёмся выше,
    // либо выбросим исключение на последней попытке.
    throw new InvalidOperationException("unreachable");
}
"}

{"path":"src/go_module.go","content":"// worker — функция-обработчик, которая работает в отдельной горутине.
//
// Она читает задачи (Job) из канала jobs и отправляет результаты (Result)
// в канал results. Параметр wg используется для корректного завершения:
// когда все воркеры закончат работу, main может дождаться их через wg.Wait().
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer wg.Done() гарантирует, что счётчик WaitGroup будет уменьшен
    // независимо от того, как именно завершится горутина (нормально или с ошибкой).
    defer wg.Done()

    // for j := range jobs — цикл, который блокируется, пока в канале нет данных.
    // Как только канал jobs закроется (producer больше не шлёт задачи),
    // цикл автоматически завершится.
    for j := range jobs {
        // process выполняет фактическую работу над задачей.
        r, err := process(j)

        // Если произошла ошибка — логируем её и переходим к следующей задаче.
        // Не прерываем весь воркер, чтобы одна неудачная задача не мешала остальным.
        if err != nil {
            log.Printf("job %d: %v", j.ID, err)
            continue
        }

        // Отправляем результат в канал results.
        // Оператор <- здесь блокирует горуطينу, пока потребитель не заберёт значение,
        // что обеспечивает естественное ограничение скорости (backpressure).
        results <- r
    }
}
"}

{"path":"src/typescript_module.ts","content":"/**
 * Модуль с утилитами для работы с асинхронными вызовами.
 */

/**
 * Создаёт «debounce»-обёртку вокруг переданной функции.
 *
 * Что делает:
 * Возвращает новую функцию, которая откладывает выполнение оригинальной `fn`
 * на `ms` миллисекунд. Если за это время обёртка вызывается снова,
 * предыдущий таймер сбрасывается и отсчёт начинается заново.
 * В итоге `fn` выполнится только один раз — через `ms` мс после
 * последнего вызова обёртки.
 *
 * Почему именно так:
 * - Тип `T extends (...a: any[]) => void` позволяет принимать функцию
 *   с любой сигнатурой аргументов, сохраняя при этом точные типы
 *   параметров (через `Parameters<T>`) и возвращаемого значения.
 *   Это делает обёртку типобезопасной: вызывающий код получает
 *   автодополнение и проверку типов как у исходной функции.
 * - Переменная `t` хранит идентификатор текущего таймера.
 *   `ReturnType<typeof setTimeout>` корректно описывает тип таймера
 *   в разных окружениях (Node.js — number, браузер — Timeout).
 * - Перед постановкой нового таймера старый снимается через
 *   `clearTimeout`, чтобы гарантировать, что функция выполнится
 *   только после паузы в `ms` мс без новых вызовов.
 * - Аргументы последнего вызова (`...args`) передаются в `fn`,
 *   потому что именно они актуальны на момент фактического выполнения.
 *
 * @param fn - функция, которую нужно «приглушить».
 * @param ms - задержка в миллисекундах до выполнения `fn`.
 * @returns функция с той же сигнатурой, что и `fn`, но с отложенным вызовом.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Идентификатор активного таймера; `undefined` означает, что таймера нет.
  let t: ReturnType<typeof setTimeout> | undefined;

  return (...args: Parameters<T>) => {
    // Сбрасываем предыдущий таймер, если он ещё не сработал,
    // чтобы отсчёт шёл от самого последнего вызова.
    if (t) clearTimeout(t);

    // Ставим новый таймер: через `ms` мс выполним `fn`
    // с аргументами текущего (последнего) вызова.
    t = setTimeout(() => fn(...args), ms);
  };
}
"}

{"path":"src/rust_module.rs","content":"use std::collections::HashMap;

/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в хеш-мапу.
///
/// Формат входной строки: пары «ключ=значение», разделённые точкой с запятой.
/// Пример: `"Name=Alice;Age=30"` -> `{"name": "Alice", "age": "30"}`.
///
/// Почему именно так:
/// - Используем ленивые итераторы (split/filter_map/map/collect), чтобы не
///   создавать промежуточные векторы — это экономит память и время.
/// - Ключи приводим к нижнему регистру и обрезаем пробелы, чтобы запросы
///   были устойчивы к регистру и лишним пробелам (" NAME = Alice " == "name").
/// - Значения тоже обрезаем, но регистр сохраняем — он может быть значимым.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';') // 1. Режем строку по ';' на отдельные пары.
        .filter_map(|p| p.split_once('=')) // 2. Оставляем только те части, где есть '='.
            // split_once возвращает Option<&(k, v)>: если '=' нет — пара
            // считается некорректной и просто отбрасывается (filter_map).
            // split_once лучше, чем splitn/split, потому что берёт первый
            // '=' и не делает лишних аллокаций.
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string())) // 3. Нормализуем ключ и значение.
            // trim() убирает пробелы по краям, to_lowercase() приводит ключ
            // к нижнему регистру, to_string() превращает &str в String.
        .collect() // 4. Собираем всё в HashMap<String, String>.
}
"}
